Lemma exW_kzero : forall segs E (m : word -> option byte) (e : expr) (p n : Z),
  edenot E e = Z_to_bv 64 p -> (0 <= p)%Z -> (0 < n)%Z -> (p + n <= 2 ^ 64)%Z -> (n < 2 ^ 64)%Z ->
  (forall i, (0 <= i < n)%Z -> m (at_ (Z_to_bv 64 p) i) = Some (Z_to_bv 8 0)) ->
