Lemma exW_sok_blk : forall segs C A m md (p n a : Z) (k : nat), al_segs = segs -> Cok C -> W C A m md ->
  live A (Z_to_bv 64 p) = Some n -> (0 <= p)%Z -> (p + n < 2 ^ 64)%Z -> (p <= a)%Z -> (a + Z.of_nat k <= p + n)%Z ->
